export const answerLabel = T('KRATAK ODGOVOR', 'SHORT ANSWER', 'KURZE ANTWORT');

// Bosnian text -> [English, German] for localize-pages.mjs.
export const copyTranslations = (() => {
  const map = {};
  const put = t => { if (t) map[t[0]] = [t[1], t[2]]; };
  put(answerLabel);
  for (const c of Object.values(pageCopy)) {
    put(c.title); put(c.desc); put(c.answer);
    for (const [q, a] of c.faq || []) { put(q); put(a); }
  }
  return map;
})();
